# Colour palettes: the 91 named palettes of pl-box (color.rs) and biome
# (palettes.js), data in palettes_data.S (generated by tools/gen_palettes.py).
#
# A palette becomes K type colours in three steps:
#   1. lift: a colour darker than luma LMIN (0.2126 r + 0.7152 g +
#      0.0722 b) is scaled up (hue kept) and, if that is not enough, blended
#      toward white until its luma is LMIN, so dark anchors stay visible on
#      the near-black background;
#   2. expand: K <= len takes K colours spread over the list (i*len/K);
#      K > len interpolates linearly along the list at K evenly spaced
#      points, which generates the missing in-between hues;
#   3. check: the palette "qualifies" for K when every pair of its K colours
#      is at least MINDIST apart (redmean colour distance, ~0..765).
# Automatic picks (every switch) and the K key only use palettes that
# qualify for the current K; --palette NAME is honoured even if it does not.

        .intel_syntax noprefix
        .include "layout.inc"

        .section .rodata
        .balign 16
LUMA_W:   .float 0.2126, 0.7152, 0.0722, 0.0
V_255:    .float 255.0, 255.0, 255.0, 255.0
V_ZERO4:  .float 0.0, 0.0, 0.0, 0.0
F_LMIN:   .float 100.0
F_255:    .float 255.0
F_256:    .float 256.0
F_2:      .float 2.0
F_4:      .float 4.0
F_HALF2:  .float 0.5
F_MIND2:  .float 3600.0                 # MINDIST = 60, squared

        .data
        .balign 64
        .globl pl_colors, pl_palette_cur
pl_colors:                              # ARGB per type, used by the renderer
        .long 0xFFFF4D4D, 0xFF4DA6FF, 0xFF5CE65C, 0xFFFFD24D
        .long 0xFFD966FF, 0xFF4DFFE1, 0xFFFF944D, 0xFFFF66B3
        .long 0xFFB3FF4D, 0xFF8C8CFF, 0xFFFFFFFF, 0xFF33CC99
        .long 0xFFCC3333, 0xFF3366CC, 0xFFE6B380, 0xFF999999
pl_palette_cur: .long -1                # -1 = the built-in colours above

        .bss
        .balign 16
lifted: .skip 16 * 16                   # lifted colours as {r, g, b, 0} floats
tmpcol: .skip 64                        # expansion output (ARGB)

        .text

# xmm0 = {r, g, b, 0} of 0xRRGGBB in edi
unpack:
        mov     eax, edi
        shr     eax, 16
        and     eax, 255
        vcvtsi2ss xmm0, xmm0, eax
        mov     eax, edi
        shr     eax, 8
        and     eax, 255
        vcvtsi2ss xmm1, xmm1, eax
        mov     eax, edi
        and     eax, 255
        vcvtsi2ss xmm2, xmm2, eax
        vinsertps xmm0, xmm0, xmm1, 0x10
        vinsertps xmm0, xmm0, xmm2, 0x20
        vinsertps xmm0, xmm0, xmm0, 0x08        # lane 3 = 0
        ret

# lift {r, g, b, 0} in xmm0 to luma >= LMIN (see the header)
lift:
        vdpps   xmm1, xmm0, [rip + LUMA_W], 0x71
        vucomiss xmm1, [rip + F_LMIN]
        jae     9f
        vxorps  xmm2, xmm2, xmm2
        vucomiss xmm1, xmm2
        jbe     2f                              # black: blend only
        vmovshdup xmm3, xmm0                    # max channel
        vmaxss  xmm3, xmm3, xmm0
        vmovhlps xmm4, xmm0, xmm0
        vmaxss  xmm3, xmm3, xmm4
        vmovss  xmm4, [rip + F_LMIN]
        vdivss  xmm4, xmm4, xmm1                # LMIN / L
        vmovss  xmm5, [rip + F_255]
        vdivss  xmm5, xmm5, xmm3                # 255 / max
        vminss  xmm4, xmm4, xmm5
        vbroadcastss xmm4, xmm4
        vmulps  xmm0, xmm0, xmm4
        vdpps   xmm1, xmm0, [rip + LUMA_W], 0x71
        vucomiss xmm1, [rip + F_LMIN]
        jae     9f
2:      vmovss  xmm2, [rip + F_LMIN]            # t = (LMIN - L) / (255 - L)
        vsubss  xmm2, xmm2, xmm1
        vmovss  xmm3, [rip + F_255]
        vsubss  xmm3, xmm3, xmm1
        vdivss  xmm2, xmm2, xmm3
        vbroadcastss xmm2, xmm2
        vmovaps xmm3, [rip + V_255]
        vsubps  xmm3, xmm3, xmm0
        vfmadd231ps xmm0, xmm3, xmm2            # c + (255 - c) t
        vinsertps xmm0, xmm0, xmm0, 0x08
9:      ret

# eax = ARGB of {r, g, b, x} in xmm0 (rounded, clamped)
pack:
        vmaxps  xmm0, xmm0, [rip + V_ZERO4]
        vminps  xmm0, xmm0, [rip + V_255]
        vcvtps2dq xmm0, xmm0
        vmovd   eax, xmm0
        shl     eax, 16
        vpextrd ecx, xmm0, 1
        shl     ecx, 8
        or      eax, ecx
        vpextrd ecx, xmm0, 2
        or      eax, ecx
        or      eax, 0xFF000000
        ret

# void pl_palette_build(u32 p, u32 k, u32 *out): K ARGB colours of palette
# p into out[0..16) (slots >= K repeat the list cyclically)
        .globl pl_palette_build
pl_palette_build:
        push    rbx
        push    r12
        push    r13
        push    r14
        push    r15                     # rsp aligned
        mov     r12d, esi               # K
        mov     r13, rdx                # out
        lea     rax, [rip + pl_palette_cols]
        mov     r14, [rax + rdi*8]
        mov     r15d, [r14]             # len
        add     r14, 4
        cmp     r15d, 16
        jbe     0f
        mov     r15d, 16
0:      xor     ebx, ebx                # lift every colour
1:      cmp     ebx, r15d
        jae     2f
        mov     edi, [r14 + rbx*4]
        call    unpack
        call    lift
        mov     eax, ebx
        shl     eax, 4
        lea     rcx, [rip + lifted]
        vmovaps [rcx + rax], xmm0
        inc     ebx
        jmp     1b
2:      xor     ebx, ebx                # slot i
3:      cmp     ebx, 16
        jae     9f
        cmp     ebx, r12d
        jae     7f
        cmp     r12d, r15d
        ja      5f
        mov     eax, ebx                # K <= len: colour i*len/K
        imul    eax, r15d
        xor     edx, edx
        div     r12d
        shl     eax, 4
        lea     rcx, [rip + lifted]
        vmovaps xmm0, [rcx + rax]
        jmp     6f
5:      lea     eax, [r15d - 1]         # K > len: t = i (len-1) / (K-1)
        imul    eax, ebx
        vcvtsi2ss xmm1, xmm1, eax
        lea     eax, [r12d - 1]
        vcvtsi2ss xmm2, xmm2, eax
        vdivss  xmm1, xmm1, xmm2
        vcvttss2si eax, xmm1            # a
        lea     ecx, [r15d - 2]
        cmp     eax, ecx
        cmovg   eax, ecx
        vcvtsi2ss xmm2, xmm2, eax
        vsubss  xmm1, xmm1, xmm2        # f
        vbroadcastss xmm1, xmm1
        shl     eax, 4
        lea     rcx, [rip + lifted]
        vmovaps xmm0, [rcx + rax]
        vmovaps xmm2, [rcx + rax + 16]
        vsubps  xmm2, xmm2, xmm0
        vfmadd231ps xmm0, xmm2, xmm1
6:      call    pack
        mov     [r13 + rbx*4], eax
        inc     ebx
        jmp     3b
7:      mov     eax, ebx                # unused slots: cycle the first K
        xor     edx, edx
        div     r12d
        mov     eax, [r13 + rdx*4]
        mov     [r13 + rbx*4], eax
        inc     ebx
        jmp     3b
9:      pop     r15
        pop     r14
        pop     r13
        pop     r12
        pop     rbx
        ret

# float pl_palette_mindist2(u32 p, u32 k): smallest squared redmean distance
# between two of palette p's K colours (as built), 1e30 for K = 1
        .globl pl_palette_mindist2
pl_palette_mindist2:
        push    rbx
        push    r12                     # rsp misaligned: one more
        push    r13
        mov     r12d, esi
        lea     rdx, [rip + tmpcol]
        call    pl_palette_build
        lea     r13, [rip + tmpcol]
        mov     eax, 0x7149f2ca         # 1e30
        vmovd   xmm7, eax
        xor     ebx, ebx                # i
1:      cmp     ebx, r12d
        jae     9f
        xor     ecx, ecx                # j < i
2:      cmp     ecx, ebx
        jae     8f
        mov     edi, [r13 + rbx*4]
        mov     esi, [r13 + rcx*4]
        call    dist2
        vminss  xmm7, xmm7, xmm0
        inc     ecx
        jmp     2b
8:      inc     ebx
        jmp     1b
9:      vmovaps xmm0, xmm7
        pop     r13
        pop     r12
        pop     rbx
        ret

# xmm0 = redmean distance^2 of ARGB edi, esi:
# (2 + rm/256) dr^2 + 4 dg^2 + (2 + (255 - rm)/256) db^2, rm = (r1 + r2)/2
# Clobbers rax, rdx, r8, xmm0..xmm6.
dist2:
        mov     eax, edi
        shr     eax, 16
        and     eax, 255
        mov     edx, esi
        shr     edx, 16
        and     edx, 255
        lea     r8d, [eax + edx]
        vcvtsi2ss xmm6, xmm6, r8d
        vmulss  xmm6, xmm6, [rip + F_HALF2]     # rm
        sub     eax, edx
        vcvtsi2ss xmm1, xmm1, eax               # dr
        mov     eax, edi
        shr     eax, 8
        and     eax, 255
        mov     edx, esi
        shr     edx, 8
        and     edx, 255
        sub     eax, edx
        vcvtsi2ss xmm2, xmm2, eax               # dg
        mov     eax, edi
        and     eax, 255
        mov     edx, esi
        and     edx, 255
        sub     eax, edx
        vcvtsi2ss xmm3, xmm3, eax               # db
        vdivss  xmm4, xmm6, [rip + F_256]
        vaddss  xmm4, xmm4, [rip + F_2]
        vmulss  xmm1, xmm1, xmm1
        vmulss  xmm0, xmm1, xmm4
        vmulss  xmm2, xmm2, xmm2
        vfmadd231ss xmm0, xmm2, [rip + F_4]
        vmovss  xmm5, [rip + F_255]
        vsubss  xmm5, xmm5, xmm6
        vdivss  xmm5, xmm5, [rip + F_256]
        vaddss  xmm5, xmm5, [rip + F_2]
        vmulss  xmm3, xmm3, xmm3
        vfmadd231ss xmm0, xmm3, xmm5
        ret

# int pl_palette_ok(u32 p, u32 k): 1 if palette p qualifies for K
        .globl pl_palette_ok
pl_palette_ok:
        push    rbx                     # rsp aligned
        call    pl_palette_mindist2
        xor     eax, eax
        vucomiss xmm0, [rip + F_MIND2]
        setae   al
        pop     rbx
        ret

# void pl_palette_set(u32 p): make p current and build pl_colors for pl.K
        .globl pl_palette_set
pl_palette_set:
        mov     [rip + pl_palette_cur], edi
        mov     esi, [rip + pl + PL_K]
        lea     rdx, [rip + pl_colors]
        jmp     pl_palette_build

# void pl_palette_refresh(void): rebuild pl_colors for the current palette
# after a type-count change
        .globl pl_palette_refresh
pl_palette_refresh:
        mov     edi, [rip + pl_palette_cur]
        test    edi, edi
        jns     pl_palette_set
        ret

# u32 pl_palette_pick(void): a random palette qualifying for pl.K other than
# the current one; if none qualifies, the non-current one with the largest
# minimum distance
        .globl pl_palette_pick
pl_palette_pick:
        push    rbx
        push    r12
        push    r13
        push    r14
        push    r15
        sub     rsp, 16                 # rsp aligned; [rsp] best distance
        lea     r14, [rip + qual]       # qualifying list
        xor     r12d, r12d              # count
        mov     r15d, -1                # best fallback
        mov     dword ptr [rsp], 0xff800000     # -inf
        xor     ebx, ebx
1:      cmp     ebx, [rip + pl_npalettes]
        jae     3f
        cmp     ebx, [rip + pl_palette_cur]
        je      2f
        mov     edi, ebx
        mov     esi, [rip + pl + PL_K]
        call    pl_palette_mindist2
        vucomiss xmm0, [rsp]
        jbe     11f
        vmovss  [rsp], xmm0
        mov     r15d, ebx
11:     vucomiss xmm0, [rip + F_MIND2]
        jb      2f
        mov     [r14 + r12*4], ebx
        inc     r12d
2:      inc     ebx
        jmp     1b
3:      mov     eax, r15d
        test    r12d, r12d
        jz      9f
        call    pl_rng_u64
        shr     rax, 32
        imul    rax, r12
        shr     rax, 32
        mov     eax, [r14 + rax*4]
9:      add     rsp, 16
        pop     r15
        pop     r14
        pop     r13
        pop     r12
        pop     rbx
        ret

# u32 pl_palette_next(int dir): the next (dir = 1) or previous (dir = -1)
# palette in list order that qualifies for pl.K; the current one if no
# other qualifies
        .globl pl_palette_next
pl_palette_next:
        push    rbx
        push    r12
        push    r13
        push    r14
        sub     rsp, 8                  # rsp aligned
        mov     r12d, edi
        mov     ebx, [rip + pl_palette_cur]
        test    ebx, ebx
        jns     0f
        mov     ebx, -1
        cmp     r12d, 0
        jg      0f
        xor     ebx, ebx
0:      mov     r13d, [rip + pl_npalettes]
        mov     r14d, r13d              # at most one full round
1:      add     ebx, r12d
        test    ebx, ebx
        jns     2f
        lea     ebx, [r13d - 1]
2:      cmp     ebx, r13d
        jb      3f
        xor     ebx, ebx
3:      cmp     ebx, [rip + pl_palette_cur]
        je      8f                      # wrapped all the way round
        dec     r14d
        js      8f
        mov     edi, ebx
        mov     esi, [rip + pl + PL_K]
        call    pl_palette_ok
        test    eax, eax
        jz      1b
8:      mov     eax, ebx
        add     rsp, 8
        pop     r14
        pop     r13
        pop     r12
        pop     rbx
        ret

# int pl_palette_find(const char *name): index by name, case-insensitive,
# ' ' and '_' accepted for '-'; -1 if unknown
        .globl pl_palette_find
pl_palette_find:
        push    rbx
        push    r12
        push    r13                     # rsp aligned
        sub     rsp, 64
        mov     r12, rdi
        xor     ecx, ecx
1:      movzx   eax, byte ptr [r12 + rcx]
        cmp     al, ' '
        je      11f
        cmp     al, '_'
        jne     2f
11:     mov     al, '-'
2:      mov     [rsp + rcx], al
        test    al, al
        jz      3f
        inc     ecx
        cmp     ecx, 63
        jb      1b
        mov     byte ptr [rsp + rcx], 0
3:      xor     ebx, ebx
4:      cmp     ebx, [rip + pl_npalettes]
        jae     8f
        lea     r13, [rip + pl_palette_names]
        mov     rsi, [r13 + rbx*8]
        mov     rdi, rsp
        call    strcasecmp@PLT
        test    eax, eax
        jz      9f
        inc     ebx
        jmp     4b
8:      mov     ebx, -1
9:      mov     eax, ebx
        add     rsp, 64
        pop     r13
        pop     r12
        pop     rbx
        ret

        .bss
        .balign 4
qual:   .skip 4 * 256
